package com.brightloop.notification;
import com.brightloop.invoice.InvoiceRepository;import com.brightloop.subscription.SubscriptionRepository;import java.math.BigDecimal;import java.time.LocalDate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class ReminderScheduler{
 private final SubscriptionRepository subscriptions;private final InvoiceRepository invoices;private final EmailNotificationService emails;public ReminderScheduler(SubscriptionRepository s,InvoiceRepository i,EmailNotificationService e){subscriptions=s;invoices=i;emails=e;}
 @Scheduled(cron="${brightloop.notifications.cron:0 0 3 * * *}") @Transactional public void reminders(){LocalDate today=LocalDate.now();for(var s:subscriptions.findByStatusAndNextBillingDateBetween("ACTIVE",today,today.plusDays(3)))emails.renewal(s.getCustomer().getEmail(),s.getSubscriptionNumber(),s.getNextBillingDate().toString());for(var invoice:invoices.findByOutstandingGreaterThanAndDueDateBetween(BigDecimal.ZERO,today,today.plusDays(3)))emails.invoiceDue(invoice.getCustomer().getEmail(),invoice.getInvoiceNumber(),invoice.getDueDate().toString());for(var invoice:invoices.findByOutstandingGreaterThanAndDueDateBefore(BigDecimal.ZERO,today))emails.overdue(invoice.getCustomer().getEmail(),invoice.getInvoiceNumber(),invoice.getDueDate().toString());}
}
